import numpy as np
from scipy.optimize import least_squares
y=dA_dt
def nm(model,p0):
    best=None
    for s in range(6):
        p=np.array(p0)*(1+0.3*np.random.randn(len(p0))) if s else np.array(p0,float)
        try:
            r=least_squares(lambda q: model(q)-y, p, max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.mean(best.fun**2)/np.var(y), np.round(best.x,4)
